	for _, tc := range cases {
		got, err := triangle(tc.a, tc.b, tc.c)
		if err != nil || got != tc.want {
			t.Fatalf("triangle(%d,%d,%d) = %q, %v; want %q", tc.a, tc.b, tc.c, got, err, tc.want)
		}
	}
	for _, tc := range [][3]int{{0, 0, 0}, {-1, 2, 2}, {1, 1, 3}, {2, 4, 2}} {
